using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization.Json;
using RCPhotoStudio.Models;

namespace RCPhotoStudio.Services
{
    internal static class DefaultPackageCatalog
    {
        // Compressed snapshot of the studio's approved package library. Embedding
        // it keeps the same factory defaults available on every installation.
        private const string CompressedPackagesBase64 =
            "";

        public static ObservableCollection<PhotoPackage> Load()
        {
            var compressed = Convert.FromBase64String(CompressedPackagesBase64);
            using (var source = new MemoryStream(compressed))
            using (var gzip = new GZipStream(source, CompressionMode.Decompress))
            {
                var serializer = new DataContractJsonSerializer(typeof(List<PhotoPackage>));
                var packages = serializer.ReadObject(gzip) as List<PhotoPackage>;
                return new ObservableCollection<PhotoPackage>(packages ?? new List<PhotoPackage>());
            }
        }
    }
}
